const ProfileBind* profile_bind_from_name(const char* name) {
    for (int i = 0; i < bind_count; i++) {
        if (strcmp(all_binds[i].name, name) == 0) {
            return &all_binds[i];
        }
    }
    return NULL;
}

void profile_bind_init_all(void) {
}

const ProfileBind* profile_bind_parse(const char* name) {
    const ProfileBind* bind = profile_bind_from_name(name);
    if (bind != NULL) return bind;
    return &all_binds[0];
}

bool profile_bind_is_none(const ProfileBind* bind) {
    return bind->type_value == 0 && bind->key_value == 0;
}

int profile_bind_from_string(const char* name, ProfileBind* out_bind) {
    if (!name || !out_bind) return -1;
    const ProfileBind* found = profile_bind_from_name(name);
    if (!found) return -1;
    *out_bind = *found;
    return 0;
}

const char* profile_bind_display_name(const ProfileBind* bind) {
    ptrdiff_t idx = bind - all_binds;
    if (idx >= 0 && idx < bind_count) {
        return display_names[idx];
    }
    return bind->name;
}
